          "en": "Formation: 읽다 → 읽- + -느냐고 물었어요 → 읽느냐고 물었어요\nThe present question-report forms practiced here are verb -느냐고, adjective -(으)냐고, noun (이)냐고. Past uses -았/었느냐고. Exercises require the specified forms; forms such as 가냐고 and 좋냐고 are also valid.",
          "zh": "构成：읽다 → 읽- + -느냐고 물었어요 → 읽느냐고 물었어요\n本课练习的现在时疑问引用形式：动词-느냐고、形容词-(으)냐고、名词(이)냐고；过去时-았/었느냐고。本课练习指定的上述形式；가냐고、좋냐고等也属于正确用法。"
