          "en": "Formation: 앉다 → 앉- + -으라고 했어요 → 앉으라고 했어요\nUse -으라고 after a consonant, -라고 after a vowel or ㄹ. A prohibition becomes -지 말라고. Requests with 주세요 for the original speaker’s benefit require -아/어 달라고, learned separately.",
          "zh": "构成：앉다 → 앉- + -으라고 했어요 → 앉으라고 했어요\n辅音后接-으라고，元音或ㄹ后接-라고；禁止用-지 말라고。原说话人为自己请求的주세요需另学-아/어 달라고。"
