          "en": "Formation: 있다 → 있- + -는지 → 어디에 있는지 몰라요 → 어디에 있는지 몰라요\nUse -는지 for present verbs and 있다/없다, -(으)ㄴ지 for present adjectives, 인지 for nouns, and -았/었는지 for past. Use -(으)ㄹ지 for future uncertainty or choices, followed by 알다, 모르다, 궁금하다, etc.",
          "zh": "构成：있다 → 있- + -는지 → 어디에 있는지 몰라요 → 어디에 있는지 몰라요\n现在时动词及있다/없다用-는지，形容词用-(으)ㄴ지，名词用인지，过去用-았/었는지；未来不确定情况或选择用-(으)ㄹ지，后接알다、모르다、궁금하다等。"
