      "ja": "動詞・形容詞の아/어形に도を付け、予想と違う結果が成り立つことを表します。名詞文は(이)어도/여도。ここでは許可の-아/어도 되다とは分け、後ろに独立した結果が続く用法を学びます。",
      "en": "Add 도 to a verb/adjective 아/어 form for a result that holds despite the condition. Nouns use (이)어도/여도. Here the next clause states an outcome, rather than permission with 되다.",
      "zh": "动词、形容词아/어形后加도，表示即使前项成立，仍出现不同于预期的结果；名词用(이)어도/여도。本课后句是独立结果，不是许可结构-아/어도 되다。"
