          "en": "Formation: 바쁘다 → 바빠 + 도 (ㅡ 탈락) → 바빠도\nAdd 도 to a verb/adjective 아/어 form for a result that holds despite the condition. Nouns use (이)어도/여도. Here the next clause states an outcome, rather than permission with 되다.",
